def get_S_range(N, D, limit, m_val=None, min_nm=0):
    if D > limit:
        return None
    if m_val is None:
        v_min = list(range(1, D + 1))
        min_S = sum(v_min)
        if D > N: return None
    else:
        if min_nm * m_val > limit:
            return None
        if m_val <= D:
            v_min = list(range(1, D + 1))
        else:
            v_min = list(range(1, D)) + [m_val]
        if v_min[-1] > limit:
            return None
        min_S = sum(v_min) + (min_nm - 1) * m_val
        if D - 1 + min_nm > N: return None
    if m_val is None:
        v_max = list(range(limit, limit - D, -1))
        rows_used = D
        max_S = sum(v_max)
    else:
        v_max = list(range(limit, limit - D, -1))
        if m_val not in v_max:
            v_max[-1] = m_val
        rows_used = D - 1 + min_nm
        max_S = sum(v_max) + (min_nm - 1) * m_val
        if rows_used > N: return None
    rows_left = N - rows_used
    v_max.sort(reverse=True)
    for k in v_max:
        current_n = min_nm if (m_val is not None and k == m_val) else 1
        capacity = (limit // k) - current_n
        take = min(rows_left, capacity)
        max_S += take * k
        rows_left -= take
    return min_S, max_S

def check_m(N, m):
    for Dr in range(1, N + 1):
        for Dc in range(1, N + 1):
            res_n = get_S_range(N, Dr, Dc, m_val=m, min_nm=2)
            if res_n is None: continue
            res_m = get_S_range(N, Dc, Dr)
            if res_m is None: continue
            if max(res_n[0], res_m[0]) <= min(res_n[1], res_m[1]):
                return True
    return False

print(f"m=100: {check_m(200, 100)}")
print(f"m=99: {check_m(200, 99)}")

